import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TextInput,
  TouchableOpacity,
  Alert,
  ActivityIndicator,
  Linking,
  KeyboardAvoidingView,
  Platform,
  Modal,
  ScrollView,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import {
  collection,
  onSnapshot,
  query,
  orderBy,
  deleteDoc,
  doc,
  addDoc,
  updateDoc,
} from 'firebase/firestore';
import { firestore, auth } from '../services/firebaseConfig';
import BottomActionBar from '../components/BottomActionBar';
import { LinearGradient } from 'expo-linear-gradient';

const UIDS_PERMITIDOS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'DibIuShhIqbApUpHAIKSG8w2dE02',
  'GOCAnVhbP7UV3CJG1fvcC0LL9Yj2',
  'wnQhp7vS63RczRny0mPcsamU7Ry2',
  'FeDkL01ukAexBWSAVIr3B7u6oZs2'
];

interface Ensaio {
  id?: string;
  data: string;
  horario: string;
  observacoes: string;
  criadoEm: any;
}

interface Devocional {
  id?: string;
  link: string;
  criadoEm: any;
}

const skeuoShadow = {
  shadowColor: '#3a256b',
  shadowOffset: { width: 0, height: 8 },
  shadowOpacity: 0.35,
  shadowRadius: 18,
  elevation: 18,
};

const neuMorphShadow = {
  shadowColor: '#7c4dff',
  shadowOffset: { width: 6, height: 6 },
  shadowOpacity: 0.25,
  shadowRadius: 12,
  elevation: 12,
};

function formatData(text: string) {
  let cleaned = text.replace(/\D/g, '');
  if (cleaned.length > 2) cleaned = cleaned.slice(0, 2) + '/' + cleaned.slice(2);
  if (cleaned.length > 5) cleaned = cleaned.slice(0, 5) + '/' + cleaned.slice(5, 9);
  return cleaned.slice(0, 10);
}

function formatHorario(text: string) {
  let cleaned = text.replace(/\D/g, '');
  if (cleaned.length > 2) cleaned = cleaned.slice(0, 2) + ':' + cleaned.slice(2, 4);
  return cleaned.slice(0, 5);
}

const GradientButton = ({ onPress, children, style = {} }) => (
  <TouchableOpacity onPress={onPress} activeOpacity={0.85} style={[{ borderRadius: 20 }, style]}>
    <View style={{ borderRadius: 20, overflow: 'hidden' }}>
      <LinearGradient
        colors={['#a084e8', '#7c4dff']}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.gradientBtn}
      >
        <Text style={styles.gradientBtnText}>{children}</Text>
      </LinearGradient>
    </View>
  </TouchableOpacity>
);

const GradientCard = ({ children, style = {} }) => (
  <LinearGradient
    colors={['#3a256b', '#1a093e']}
    start={{ x: 0, y: 0 }}
    end={{ x: 1, y: 1 }}
    style={[styles.gradientCard, style]}
  >
    {children}
  </LinearGradient>
);

function isYoutubeLink(link: string) {
  return /^(https?:\/\/)?(www\.)?(youtube\.com|youtu\.be)\//.test(link);
}

export default function EnsaiosScreen() {
  const navigation = useNavigation();
  const [ensaios, setEnsaios] = useState<Ensaio[]>([]);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [novaData, setNovaData] = useState('');
  const [novoHorario, setNovoHorario] = useState('');
  const [novasObs, setNovasObs] = useState('');
  const [editandoId, setEditandoId] = useState<string | null>(null);
  const [editData, setEditData] = useState('');
  const [editHorario, setEditHorario] = useState('');
  const [editObs, setEditObs] = useState('');
  const [devocional, setDevocional] = useState<Devocional | null>(null);
  const [novoLink, setNovoLink] = useState('');
  const [editandoDevocional, setEditandoDevocional] = useState(false);

  const [modalAviso, setModalAviso] = useState(false);
  const [modalDevocional, setModalDevocional] = useState(false);

  useEffect(() => {
    const uid = auth.currentUser?.uid ?? null;
    setUidAtual(uid);

    const ensaiosQuery = query(
      collection(firestore, 'ensaios'),
      orderBy('criadoEm', 'desc')
    );
    const devocionalQuery = query(
      collection(firestore, 'devocional'),
      orderBy('criadoEm', 'desc')
    );

    const unsubEnsaios = onSnapshot(ensaiosQuery, (querySnapshot) => {
      const data = querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data(),
      }));
      setEnsaios(data as Ensaio[]);
      setLoading(false);
    });

    const unsubDevocional = onSnapshot(devocionalQuery, (querySnapshot) => {
      const docs = querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data(),
      }));
      setDevocional(docs[0] || null);
    });

    return () => {
      unsubEnsaios();
      unsubDevocional();
    };
  }, []);

  const podeEditar = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);

  const excluirEnsaio = async (id: string) => {
    if (!podeEditar) return;
    try {
      await auth.currentUser?.getIdToken(true);
      await deleteDoc(doc(firestore, 'ensaios', id));
      setEnsaios(prev => prev.filter(e => e.id !== id));
    } catch (error: any) {
      console.log('Erro ao excluir ensaio:', error);
    }
  };

  const handleCriarEnsaio = async () => {
    if (!novaData.trim() || !novoHorario.trim()) {
      Alert.alert('Atenção', 'Preencha a data e o horário.');
      return;
    }
    try {
      await addDoc(collection(firestore, 'ensaios'), {
        data: novaData,
        horario: novoHorario,
        observacoes: novasObs,
        criadoEm: new Date(),
      });
      setNovaData('');
      setNovoHorario('');
      setNovasObs('');
      setModalAviso(false);
    } catch {
      Alert.alert('Erro', 'Não foi possível criar o ensaio.');
    }
  };

  const handleEditarEnsaio = (ensaio: Ensaio) => {
    setEditandoId(ensaio.id!);
    setEditData(ensaio.data);
    setEditHorario(ensaio.horario);
    setEditObs(ensaio.observacoes);
  };

  const handleSalvarEdicao = async () => {
    if (!editData.trim() || !editHorario.trim() || !editandoId) {
      Alert.alert('Atenção', 'Preencha a data e o horário.');
      return;
    }
    try {
      await updateDoc(doc(firestore, 'ensaios', editandoId), {
        data: editData,
        horario: editHorario,
        observacoes: editObs,
      });
      setEditandoId(null);
      setEditData('');
      setEditHorario('');
      setEditObs('');
    } catch {
      Alert.alert('Erro', 'Não foi possível salvar o ensaio.');
    }
  };

  const handleSalvarDevocional = async () => {
    if (!novoLink.trim()) {
      Alert.alert('Atenção', 'Informe o link do devocional.');
      return;
    }
    try {
      if (devocional && devocional.id) {
        await updateDoc(doc(firestore, 'devocional', devocional.id), {
          link: novoLink,
        });
      } else {
        await addDoc(collection(firestore, 'devocional'), {
          link: novoLink,
          criadoEm: new Date(),
        });
      }
      setEditandoDevocional(false);
      setNovoLink('');
      setModalDevocional(false);
    } catch {
      Alert.alert('Erro', 'Não foi possível salvar o devocional.');
    }
  };

  const handleDataChange = (text: string) => setNovaData(formatData(text));
  const handleHorarioChange = (text: string) => setNovoHorario(formatHorario(text));
  const handleEditDataChange = (text: string) => setEditData(formatData(text));
  const handleEditHorarioChange = (text: string) => setEditHorario(formatHorario(text));

  const renderItem = ({ item }: { item: Ensaio }) => (
    <GradientCard style={{ marginBottom: 14 }}>
      <View style={neuMorphShadow}>
        {editandoId === item.id && podeEditar ? (
          <>
            <TextInput
              style={[styles.input, neuMorphShadow]}
              value={editData}
              onChangeText={handleEditDataChange}
              placeholder="Data (ex: 10/06/2025)"
              placeholderTextColor="#e0d7fa"
              keyboardType="numeric"
              maxLength={10}
            />
            <TextInput
              style={[styles.input, neuMorphShadow]}
              value={editHorario}
              onChangeText={handleEditHorarioChange}
              placeholder="Horário (ex: 19:30)"
              placeholderTextColor="#e0d7fa"
              keyboardType="numeric"
              maxLength={5}
            />
            <TextInput
              style={[styles.input, { minHeight: 40 }, neuMorphShadow]}
              value={editObs}
              onChangeText={setEditObs}
              placeholder="Observações"
              placeholderTextColor="#e0d7fa"
              multiline
            />
            <View style={{ flexDirection: 'row', marginTop: 6, justifyContent: 'space-between' }}>
              <GradientButton
                onPress={handleSalvarEdicao}
                style={{ flex: 1, marginRight: 8 }}
              >
                Salvar
              </GradientButton>
              <GradientButton
                onPress={() => setEditandoId(null)}
                style={{ flex: 1, marginLeft: 8 }}
              >
                Cancelar
              </GradientButton>
            </View>
          </>
        ) : (
          <>
            <Text style={styles.avisoTitulo}>Data: {item.data}</Text>
            <Text style={styles.avisoMensagem}>Horário: {item.horario}</Text>
            {item.observacoes ? (
              <Text style={styles.avisoMensagem}>Obs: {item.observacoes}</Text>
            ) : null}
            <Text style={styles.avisoData}>
              {item.criadoEm?.toDate ? item.criadoEm.toDate().toLocaleString() : ''}
            </Text>
            {podeEditar && (
              <View style={{ flexDirection: 'row', marginTop: 8, justifyContent: 'space-between' }}>
                <GradientButton
                  onPress={() => handleEditarEnsaio(item)}
                  style={{ flex: 1, marginRight: 8 }}
                >
                  Editar
                </GradientButton>
                <GradientButton
                  onPress={() => excluirEnsaio(item.id!)}
                  style={{ flex: 1, marginLeft: 8 }}
                >
                  Excluir
                </GradientButton>
              </View>
            )}
          </>
        )}
      </View>
    </GradientCard>
  );

  return (
    <LinearGradient
      colors={['#2d145e', '#3a256b', '#1a093e']}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
      style={styles.gradientBg}
    >
      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
        keyboardVerticalOffset={80}
      >
        <View style={{ flex: 1 }}>
          {/* Top navigation buttons */}
          <View style={styles.topNavRow}>
            <LinearGradient
              colors={['#7c4dff', '#3a256b']}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={styles.topNavBtnGradient}
            >
              <TouchableOpacity
                style={[styles.topNavBtn, skeuoShadow]}
                onPress={() => navigation.navigate('Inicio')}
                activeOpacity={0.85}
              >
                <Text style={styles.topNavBtnText}>🏠 Home</Text>
              </TouchableOpacity>
            </LinearGradient>
            <LinearGradient
              colors={['#7c4dff', '#3a256b']}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={styles.topNavBtnGradient}
            >
              <TouchableOpacity
                style={[styles.topNavBtn, skeuoShadow]}
                onPress={() => navigation.goBack()}
                activeOpacity={0.85}
              >
                <Text style={styles.topNavBtnText}>🔙</Text>
              </TouchableOpacity>
            </LinearGradient>
          </View>

          <View style={styles.container}>
            <Text style={[styles.title, { color: '#fff' }]}>🎶 Ensaios</Text>

            {/* ScrollView apenas nos avisos */}
            <View style={{ flex: 1, maxHeight: 320 }}>
              <ScrollView
                contentContainerStyle={{ paddingBottom: 20 }}
                showsVerticalScrollIndicator={true}
              >
                {loading ? (
                  <ActivityIndicator size="large" color="#7c4dff" style={{ marginTop: 30 }} />
                ) : ensaios.length === 0 ? (
                  <Text style={{ color: '#888', marginTop: 30 }}>Nenhum ensaio cadastrado.</Text>
                ) : (
                  ensaios.map(item => renderItem({ item }))
                )}
              </ScrollView>
            </View>

            <Text style={[styles.title, { color: '#fff' }]}>🙌🏼 Devocional</Text>
            {devocional && !editandoDevocional && devocional.link ? (
              <GradientCard style={{ marginBottom: 18 }}>
                <View style={neuMorphShadow}>
                  <Text style={{ fontWeight: 'bold', marginBottom: 6, color: '#fff', textAlign: 'center' }}>
                    PLAY PARA O YOUTUBE:
                  </Text>
                  <TouchableOpacity
                    style={styles.youtubePlayBtn}
                    onPress={() => Linking.openURL(devocional.link)}
                    activeOpacity={0.85}
                  >
                    <LinearGradient
                      colors={['#7c4dff', '#3a256b']}
                      start={{ x: 0, y: 0 }}
                      end={{ x: 1, y: 1 }}
                      style={styles.youtubePlayBtnGradient}
                    >
                      <Text style={styles.youtubeIcon}>▶️</Text>
                    </LinearGradient>
                  </TouchableOpacity>
                </View>
              </GradientCard>
            ) : null}
          </View>

          {/* Modal para novo ensaio */}
          <Modal
            visible={modalAviso}
            transparent
            animationType="fade"
            onRequestClose={() => setModalAviso(false)}
          >
            <View style={styles.modalBg}>
              <View style={[styles.modalBox, neuMorphShadow]}>
                <Text style={styles.modalTitle}>Novo Ensaio</Text>
                <TextInput
                  style={[styles.input, neuMorphShadow]}
                  placeholder="Data (ex: 10/06/2025)"
                  value={novaData}
                  onChangeText={handleDataChange}
                  placeholderTextColor="#e0d7fa"
                  keyboardType="numeric"
                  maxLength={10}
                />
                <TextInput
                  style={[styles.input, neuMorphShadow]}
                  placeholder="Horário (ex: 19:30)"
                  value={novoHorario}
                  onChangeText={handleHorarioChange}
                  placeholderTextColor="#e0d7fa"
                  keyboardType="numeric"
                  maxLength={5}
                />
                <TextInput
                  style={[styles.input, { minHeight: 40 }, neuMorphShadow]}
                  placeholder="Observações"
                  value={novasObs}
                  onChangeText={setNovasObs}
                  placeholderTextColor="#e0d7fa"
                  multiline
                />
                <GradientButton onPress={handleCriarEnsaio} style={{ marginTop: 8 }}>
                  Salvar
                </GradientButton>
                <GradientButton onPress={() => setModalAviso(false)} style={{ marginTop: 8 }}>
                  Cancelar
                </GradientButton>
              </View>
            </View>
          </Modal>

          {/* Modal para devocional */}
          <Modal
            visible={modalDevocional}
            transparent
            animationType="fade"
            onRequestClose={() => setModalDevocional(false)}
          >
            <View style={styles.modalBg}>
              <View style={[styles.modalBox, neuMorphShadow]}>
                <Text style={styles.modalTitle}>Novo Devocional</Text>
                <TextInput
                  style={[styles.input, neuMorphShadow]}
                  placeholder="Link do devocional"
                  value={novoLink}
                  onChangeText={setNovoLink}
                  placeholderTextColor="#e0d7fa"
                />
                <GradientButton onPress={handleSalvarDevocional} style={{ marginTop: 8 }}>
                  Salvar
                </GradientButton>
                <GradientButton onPress={() => setModalDevocional(false)} style={{ marginTop: 8 }}>
                  Cancelar
                </GradientButton>
              </View>
            </View>
          </Modal>
        </View>
      </KeyboardAvoidingView>

      {/* Barra flutuante sobre o conteúdo */}
      <BottomActionBar
        onNovoEnsaio={() => {
          if (podeEditar) {
            setModalAviso(true);
          } else {
            Alert.alert('Acesso restrito', 'Você não tem permissão para essa ação.');
          }
        }}
        onNovoDevocional={() => {
          if (podeEditar) {
            setModalDevocional(true);
          } else {
            Alert.alert('Acesso restrito', 'Você não tem permissão para essa ação.');
          }
        }}
        onEditarDevocional={() => {
          if (podeEditar) {
            setEditandoDevocional(true);
            setNovoLink(devocional?.link || '');
            setModalDevocional(true);
          } else {
            Alert.alert('Acesso restrito', 'Você não tem permissão para essa ação.');
          }
        }}
        skeuoShadow={skeuoShadow}
      />
    </LinearGradient>
  );
}

